    # 5. Modules, Map/Set & Symbols - 30 Qs
    mod_items = [
        ("What are ES6 modules (ESM)?", "ES6 modules are the official JavaScript standard format for modular code, using 'export' to share values and 'import' to consume them.", "Easy", "Concept", "// utils.js\nexport const add = (a, b) => a + b;\n// app.js\nimport { add } from './utils.js';", "What is the file extension often used in Node.js for ESM?"),
        ("What is the difference between named export and default export in ES6 modules?", "A module can have multiple named exports (imported with matching names inside {}). A module can have at most ONE default export (imported with any name without {}).", "Easy", "Comparison", "// export default Component;\n// import MyComponent from './Component';", "Can a module have both named and default exports?"),
        ("Can a single file have both default export and named exports?", "Yes! You can have one default export along with any number of named exports in the same module.", "Easy", "Practical", "export default function main() {}\nexport const helper = () => {};\n// In importer:\nimport main, { helper } from './lib.js';", "How do you rename named imports?"),
        ("How do you rename named imports using the 'as' keyword?", "Use 'as': import { originalName as newName } from './module.js'.", "Easy", "Practical", "import { render as domRender } from 'react-dom';", "How do you import all exports into an object?"),
        ("How do you import all exports of a module into a single namespace object?", "Use import * as namespace from './module.js'.", "Easy", "Practical", "import * as MathUtils from './math.js';\nMathUtils.add(1, 2);", "What is dynamic import()?"),
        ("What is dynamic import() in JavaScript?", "dynamic import(modulePath) loads a module asynchronously on demand and returns a Promise that resolves to the module namespace.", "Intermediate", "Concept", "const module = await import('./analytics.js');", "Why is dynamic import essential for code-splitting?"),
        ("What is the difference between CommonJS and ES Modules?", "CommonJS (require/module.exports) is synchronous and used by Node.js traditionally. ES Modules (import/export) are asynchronous, statically analyzable, and supported natively in browsers and modern Node.", "Intermediate", "Comparison", "// CommonJS\nconst fs = require('fs');\n// ESM\nimport fs from 'fs';", "Why does tree-shaking require ES modules?"),
        ("Why does tree-shaking require ES Modules instead of CommonJS?", "ESM imports and exports are static (determined at compile-time before execution), allowing bundlers to detect and remove unused dead code reliably. CommonJS is dynamic at runtime.", "Intermediate", "Concept", "", "What script tag attribute enables ES modules in HTML?"),
        ("How do you enable ES Modules in browser HTML?", "Add type='module' to the <script> tag: <script type='module' src='app.js'></script>.", "Easy", "Practical", "<script type=\"module\" src=\"app.js\"></script>", "Are script type='module' tags deferred by default?"),
        ("Are <script type='module'> tags deferred by default?", "Yes. Module scripts automatically behave as if 'defer' is present; they download in parallel and execute only after HTML parsing completes.", "Intermediate", "Concept", "", "What is CORS requirement for module scripts?"),
        ("Why do ES module scripts in browsers require CORS or an HTTP server to load?", "Browsers block module imports over the file:// protocol due to cross-origin security restrictions. Modules must be served via http:// or https://.", "Intermediate", "Security", "", "What is a Set in ES6?"),
        ("What is a Set in ES6?", "A Set is a built-in collection of unique values where each value may occur only once.", "Easy", "Concept", "const set = new Set([1, 2, 2, 3]);\nconsole.log(set.size); // 3", "What method checks if a value exists in a Set?"),
        ("What are the primary methods of a Set in ES6?", ".add(val), .has(val), .delete(val), .clear(), and the .size property.", "Easy", "Practical", "const s = new Set();\ns.add('a');\ns.has('a'); // true\ns.delete('a');\ns.size; // 0", "What is the time complexity of Set.prototype.has()?"),
        ("What is the time complexity of Set.prototype.has() vs Array.prototype.includes()?", "Set.prototype.has() is O(1) constant time hash lookup. Array.prototype.includes() is O(n) linear search.", "Intermediate", "Comparison", "", "Why is Set ideal for large lookup collections?"),
        ("What is a Map in ES6?", "A Map is an ordered collection of key-value pairs where ANY data type (including objects, functions, and primitives) can be used as keys.", "Easy", "Concept", "const map = new Map();\nconst keyObj = {};\nmap.set(keyObj, 'data');", "How does Map differ from a plain object?"),
        ("What are three key differences between a Map and a plain object?", "1. Map keys can be of ANY type (objects, functions); object keys are strings/symbols. 2. Map preserves insertion order. 3. Map has an explicit .size property (no Object.keys needed).", "Intermediate", "Comparison", "map.set(btn, 'handler');\nmap.size; // 1", "How do you iterate over a Map?"),
        ("What are the primary methods of a Map in ES6?", ".set(key, val), .get(key), .has(key), .delete(key), .clear(), and .size.", "Easy", "Practical", "const m = new Map();\nm.set('id', 101);\nm.get('id'); // 101", "What does map.get(nonExistentKey) return?"),
        ("What is a WeakSet in ES6?", "A WeakSet is a Set that can ONLY store objects and holds weak references to them, allowing unreferenced objects to be garbage collected.", "Intermediate", "Concept", "const ws = new WeakSet();", "Can you iterate over a WeakSet?"),
        ("Why can you NOT iterate or read .size on a WeakSet or WeakMap?", "Because the garbage collector can reclaim objects at any non-deterministic moment, the collection contents cannot be enumerated stably.", "Advanced", "Concept", "", "What is WeakMap?"),
        ("What is a WeakMap in ES6?", "A WeakMap is a Map whose keys MUST be objects (or non-registered symbols) held as weak references, preventing memory leaks.", "Intermediate", "Concept", "const wm = new WeakMap();\nwm.set(domElement, { clicks: 0 });", "Why is WeakMap great for private data and DOM metadata?"),
        ("What is a Symbol in ES6?", "A Symbol is a unique, immutable primitive data type often used as hidden or collision-free object property keys.", "Intermediate", "Concept", "const id = Symbol('id');\nconst id2 = Symbol('id');\nid === id2; // false!", "Are two Symbols with the same description equal?"),
        ("Are two Symbols created with Symbol('desc') equal?", "No! Every call to Symbol() returns a completely unique Symbol primitive: Symbol('a') === Symbol('a') is false.", "Easy", "Concept", "Symbol('x') === Symbol('x'); // false", "How do you create shared global symbols?"),
        ("What is the Global Symbol Registry and how do you access it?", "Use Symbol.for(key). If a symbol with that key exists globally, it returns it; otherwise it creates and registers a new global symbol.", "Intermediate", "Practical", "const s1 = Symbol.for('app');\nconst s2 = Symbol.for('app');\ns1 === s2; // true!", "What does Symbol.keyFor do?"),
        ("What are Well-Known Symbols in JavaScript?", "Built-in symbols that expose internal language algorithms, such as Symbol.iterator, Symbol.hasInstance, and Symbol.toStringTag.", "Advanced", "Concept", "", "What does Symbol.iterator do?"),
        ("What does Symbol.iterator do in JavaScript?", "It specifies the default iterator function for an object. Objects implementing [Symbol.iterator]() can be used in for...of loops and spread operators.", "Intermediate", "Concept", "const iterable = {\n  *[Symbol.iterator]() { yield 1; yield 2; }\n};\nfor (const x of iterable) console.log(x); // 1, 2", "How do you make any custom object iterable?"),
        ("Modules MCQ: Which syntax correctly imports a default export?", "Option A is correct. Default exports are imported without curly braces.", "Easy", "MCQ", "", {"A": "import MyComp from './Comp';", "B": "import { MyComp } from './Comp';", "C": "import * as MyComp from './Comp';", "D": "require(MyComp)"}, "A", "When are curly braces needed?"),
        ("Modules MCQ: What is the main security reason ES modules require an HTTP server in browsers?", "Option C is correct. Browser CORS policies block module file imports over the local file:// protocol.", "Intermediate", "MCQ", "", {"A": "HTML5 restriction", "B": "CSS loading rules", "C": "CORS security policy", "D": "V8 memory limit"}, "C", "How do you serve files locally?"),
        ("Map/Set MCQ: What does new Set([1, 2, 2, 3]).size return?", "Option B is correct. Set discards duplicates; size is 3.", "Easy", "MCQ", "", {"A": "4", "B": "3", "C": "2", "D": "undefined"}, "B", "What values does the set contain?"),
        ("Map Coding: Write a function to count the frequency of words in an array using a Map.", "function wordCount(words) { const map = new Map(); for (const w of words) map.set(w, (map.get(w) || 0) + 1); return map; }", "Easy", "Coding", "function wordCount(words) {\n  const m = new Map();\n  for (const w of words) {\n    m.set(w, (m.get(w) || 0) + 1);\n  }\n  return m;\n}", "What does map.get(w) || 0 handle?"),
        ("Symbol Output: What is logged by: const id = Symbol('id'); const obj = { [id]: 123, name: 'A' }; console.log(Object.keys(obj));?", "Output: ['name']. Symbol keys are non-enumerable in Object.keys() and for...in loops. Use Object.getOwnPropertySymbols(obj) to see symbols.", "Intermediate", "Output", "const id = Symbol('id');\nconst obj = { [id]: 123, name: 'A' };\nconsole.log(Object.keys(obj)); // ['name']", "How do you access symbol keys on an object?")
    ]
