        ("What is String.prototype.replaceAll() in ES2021?", "replaceAll(search, replaceWith) replaces all occurrences of a string or regex match without needing /g regex.", "Easy", "Practical", "'a-b-a'.replaceAll('a', 'z'); // 'z-b-z'", "What does replace('a', 'z') do without regex?"),
        ("What are Numeric Separators in ES2021?", "Underscores (_) used inside numeric literals to make large numbers readable: const ms = 1_000_000;.", "Easy", "Practical", "const num = 1_000_000;", "Does the underscore change the numeric value?"),
